import express from 'express';
import { createProxyMiddleware } from 'http-proxy-middleware';
import cors from 'cors';
import dotenv from 'dotenv';
import cookieParser from 'cookie-parser';
// Tải các biến môi trường từ file .env
dotenv.config();
// Khởi tạo ứng dụng Express
const app = express();
const PORT = process.env.PORT || 3000;
// Xử lý preflight request
app.options('*', cors({
    origin: true,
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With', 'X-Access-Token', 'X-Refresh-Token']
}));
// Cấu hình CORS (Cross-Origin Resource Sharing)
app.use(cors({
    origin: (origin, callback) => {
        const allowedOrigins = [
            'http://localhost:3000', // API Gateway
            'http://localhost:3004', // Ứng dụng Frontend
            'http://localhost:3002', // Dịch vụ Bài viết
            'http://localhost:3005', // Dịch vụ Xác thực
            'http://localhost:3008', // Dịch vụ Bình luận
            'http://localhost:3009', // Dịch vụ Danh mục
        ];
        // Cho phép request không có origin (như từ Postman, curl, v.v.)
        if (!origin || allowedOrigins.indexOf(origin) !== -1) {
            callback(null, true);
        }
        else {
            callback(new Error('Not allowed by CORS'));
        }
    },
    credentials: true, // Cho phép gửi cookie qua CORS
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With', 'X-Access-Token', 'X-Refresh-Token'],
    exposedHeaders: ['X-Access-Token', 'X-Refresh-Token']
}));
// Các middleware cơ bản
app.use(express.json()); // Phân tích dữ liệu JSON từ request
app.use(express.urlencoded({ extended: true })); // Phân tích dữ liệu form-urlencoded
app.use(cookieParser()); // Xử lý cookie
// Health check endpoint
app.get('/health', (req, res) => {
    res.status(200).json({
        status: 'UP',
        timestamp: new Date().toISOString(),
        service: 'API Gateway',
        version: '1.0.0'
    });
});
// Middleware parse JSON body
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(cookieParser());
// Middleware ghi log chi tiết các request
app.use((req, res, next) => {
    console.log('\n=== NEW REQUEST ===');
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
    console.log('Headers:', JSON.stringify(req.headers, null, 2));
    // Lưu lại body gốc để log
    const originalSend = res.send;
    res.send = function (body) {
        console.log('Response Status Code:', res.statusCode);
        console.log('Response Headers:', JSON.stringify(res.getHeaders(), null, 2));
        console.log('Response Body:', body);
        return originalSend.call(this, body);
    };
    next();
});
// Cấu hình proxy cho Dịch vụ Xác thực
const authProxy = createProxyMiddleware({
    target: process.env.AUTH_SERVICE_URL || 'http://localhost:3005',
    changeOrigin: true,
    pathRewrite: {
        '^/api/auth': '/auth' // Chuyển /api/auth/... thành /auth/...
        // Giữ nguyên /auth
    },
    ws: true,
    logLevel: 'debug',
    secure: false,
    onProxyReq: (proxyReq, req, res) => {
        console.log('\n=== PROXY REQUEST ===');
        console.log(`[${new Date().toISOString()}] Forwarding: ${req.method} ${req.originalUrl}`);
        console.log('Headers:', JSON.stringify(req.headers, null, 2));
        // Thêm header Content-Type nếu chưa có
        if (!proxyReq.getHeader('content-type')) {
            proxyReq.setHeader('Content-Type', 'application/json');
        }
        // Nếu có body, gửi lại body
        if (req.body) {
            const bodyData = typeof req.body === 'string' ? req.body : JSON.stringify(req.body);
            proxyReq.setHeader('Content-Length', Buffer.byteLength(bodyData));
            proxyReq.write(bodyData);
        }
    },
    onProxyRes: (proxyRes, req, res) => {
        console.log('\n=== PROXY RESPONSE ===');
        console.log(`[${new Date().toISOString()}] Received response for: ${req.method} ${req.originalUrl}`);
        console.log('Status Code:', proxyRes.statusCode);
        // Lưu lại để đọc body
        const originalProxyData = [];
        proxyRes.on('data', (chunk) => {
            originalProxyData.push(chunk);
        });
        proxyRes.on('end', () => {
            const body = Buffer.concat(originalProxyData).toString();
            if (body) {
                console.log('Response Body:', body);
            }
        });
    },
    onError: (err, req, res) => {
        console.error('\n=== PROXY ERROR ===');
        console.error(`[${new Date().toISOString()}] Lỗi khi chuyển tiếp yêu cầu đến Auth Service`);
        console.error('Error:', err);
        if (!res.headersSent) {
            const errorResponse = {
                success: false,
                message: 'Lỗi kết nối đến dịch vụ xác thực',
                error: process.env.NODE_ENV === 'development' ? err.message : undefined
            };
            if (process.env.NODE_ENV === 'development') {
                errorResponse.details = {
                    code: err.code || 'UNKNOWN_ERROR',
                    stack: err.stack
                };
            }
            res.status(502).json(errorResponse);
        }
    }
});
// Sử dụng proxy cho các route xác thực
app.use('/api/auth', authProxy);
app.use('/auth', authProxy);
const createServiceProxy = (config) => {
    const { path, target, pathRewrite } = config;
    const proxy = createProxyMiddleware({
        target,
        changeOrigin: true,
        pathRewrite: pathRewrite || { [`^${path}`]: '' },
        logLevel: 'debug',
        onProxyReq: (proxyReq, req, res) => {
            console.log(`[${path} Proxy] Chuyển tiếp: ${req.method} ${req.originalUrl}`);
        },
        onError: (err, req, res) => {
            console.error(`[${path} Proxy] Lỗi:`, err);
            if (!res.headersSent) {
                res.status(500).json({
                    success: false,
                    message: 'Lỗi kết nối đến dịch vụ',
                    error: err.message
                });
            }
        }
    });
    app.use(path, proxy);
};
// Cấu hình các dịch vụ
const services = [
    // Posts service - Chuyển tiếp tất cả các yêu cầu /api/posts/... đến dịch vụ bài viết
    {
        path: '/api/posts',
        target: 'http://localhost:3002/api',
        pathRewrite: { '^/api/posts': '/posts' }
    },
    // Hỗ trợ cả /posts trực tiếp
    {
        path: '/posts',
        target: 'http://localhost:3002/api',
        pathRewrite: { '^/posts': '/posts' }
    },
    // Comments service
    {
        path: '/api/comments',
        target: 'http://localhost:3008',
        pathRewrite: { '^/api/comments': '' }
    },
    // Categories service
    {
        path: '/api/categories',
        target: 'http://localhost:3009',
        pathRewrite: { '^/api/categories': '' }
    },
    // Tags endpoints (handled by posts service)
    {
        path: '/api/tags',
        target: 'http://localhost:3002',
        pathRewrite: { '^/api/tags': '/api/tags' }
    }
];
// Tạo proxy cho từng dịch vụ
services.forEach(service => createServiceProxy(service));
// Xử lý lỗi toàn cục
app.use((err, req, res, next) => {
    console.error('[API-Gateway] Lỗi:', err);
    res.status(500).json({
        success: false,
        message: 'Lỗi máy chủ nội bộ',
        error: process.env.NODE_ENV === 'development' ? err.message : {}
    });
});
// Khởi động máy chủ
app.listen(PORT, () => {
    console.log(`[API-Gateway] Máy chủ đang chạy tại cổng ${PORT}`);
});
